mapper.select:
SELECT id, allocation_id, attempt_id, owner_id, execution_authorization_id, status, version
FROM outbound_order
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND allocation_id=#{allocationId}
AND attempt_id=#{attemptId} FOR UPDATE

SELECT id, allocation_id, attempt_id, owner_id, execution_authorization_id, status, version
FROM outbound_order
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id} FOR UPDATE

SELECT id, order_id, order_line_id, sku_id, allocated_qty, picked_physical_qty, picked_posted_qty, packed_physical_qty, packed_posted_qty, shipped_physical_qty, shipped_posted_qty, cancelled_qty, cancelled_posted_qty, base_unit, stock_sync_status, version
FROM outbound_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId} FOR UPDATE

SELECT id, order_id, order_line_id, sku_id, allocated_qty, picked_physical_qty, picked_posted_qty, packed_physical_qty, packed_posted_qty, shipped_physical_qty, shipped_posted_qty, cancelled_qty, cancelled_posted_qty, base_unit, stock_sync_status, version
FROM outbound_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND order_id=#{orderId}
AND order_line_id=#{orderLineId} FOR UPDATE

mapper.update:
UPDATE outbound_order
SET status=#{status}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{orderId}

UPDATE outbound_line
SET picked_physical_qty=picked_physical_qty+#{qty}, stock_sync_status='PENDING', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}

UPDATE outbound_line
SET picked_posted_qty=picked_posted_qty+#{qty}, stock_sync_status=#{syncStatus}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND picked_posted_qty+#{qty}<=picked_physical_qty

UPDATE outbound_line
SET packed_physical_qty=packed_physical_qty+#{qty}, stock_sync_status='PENDING', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}

UPDATE outbound_line
SET shipped_physical_qty=shipped_physical_qty+#{qty}, stock_sync_status='PENDING', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND shipped_physical_qty+#{qty}<=packed_physical_qty

UPDATE outbound_line
SET shipped_posted_qty=shipped_posted_qty+#{qty}, stock_sync_status=#{syncStatus}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND shipped_posted_qty+#{qty}<=shipped_physical_qty

UPDATE outbound_line
SET cancelled_qty=cancelled_qty+#{qty}, stock_sync_status='PENDING', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}

mapper.select:
