FROM outbound_task
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id} FOR UPDATE

mapper.update:
UPDATE outbound_task
SET assignee_id=#{workerId}, claim_epoch=#{epoch}, action_id=#{actionId}, device_command_id=#{deviceCommandId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}

UPDATE outbound_task
SET completed_qty=completed_qty+#{qty}, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}

mapper.select:
SELECT id, allocation_id, attempt_id, owner_id, execution_authorization_id, status, version, created_at
FROM outbound_order
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}

    AND (created_at < #{page.time} OR (created_at = #{page.time} AND id < #{page.id}))

ORDER BY created_at DESC, id DESC
LIMIT #{page.fetchLimit}

SELECT id, allocation_id, attempt_id, owner_id, execution_authorization_id, status, version, created_at
FROM outbound_order
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}

SELECT id, order_line_id, sku_id, allocated_qty, picked_physical_qty, picked_posted_qty, packed_physical_qty, packed_posted_qty, shipped_physical_qty, shipped_posted_qty, cancelled_qty, cancelled_posted_qty, base_unit, stock_sync_status, version
FROM outbound_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND order_id=#{orderId}
ORDER BY order_line_id

SELECT id, task_type, document_id, document_line_id, planned_qty, completed_qty, state, action_id, device_command_id
FROM outbound_task
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND document_id=#{orderId}
ORDER BY created_at

SELECT COALESCE(SUM(planned_qty-completed_qty),0) FROM outbound_task
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND document_line_id=#{lineId}
    AND task_type='PICK' AND state IN ('PLANNED','STARTED')

mapper.update:
UPDATE outbound_task SET state='CANCELLED', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND document_line_id=#{lineId}
    AND task_type='PICK' AND state IN ('PLANNED','STARTED')

UPDATE outbound_bucket_progress SET shipped_physical_qty=shipped_physical_qty+#{qty},version=version+1,updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND line_id=#{lineId}
    AND location_id=#{locationId} AND lot_id=#{lotId} AND shipped_physical_qty+#{qty}<=picked_posted_qty

UPDATE outbound_line SET cancelled_posted_qty=cancelled_posted_qty+#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND id=#{lineId}
  AND cancelled_posted_qty+#{qty}<=cancelled_qty

mapper.select:
SELECT EXISTS(SELECT 1 FROM outbound_task WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND document_id=#{o} AND document_line_id=#{line}
  AND device_command_id IS NOT NULL AND state<>'COMPLETED')
  OR EXISTS(SELECT 1 FROM outbound_line WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND order_id=#{o} AND id=#{line}
  AND (picked_physical_qty<>picked_posted_qty OR shipped_physical_qty<>shipped_posted_qty))
  OR EXISTS(SELECT 1 FROM source_effect f JOIN source_command c ON c.enterprise_id=f.enterprise_id
    AND c.warehouse_id=f.warehouse_id AND c.business_effect_key=f.id
    WHERE f.enterprise_id=#{e} AND f.warehouse_id=#{w} AND f.fact_parent_id=#{o} AND f.fact_line_id=#{line}
    AND f.source_service='wms-outbound' AND f.fact_type='SUB_ACTION' AND f.action IN ('PICK','CANCEL') AND NOT JSON_CONTAINS_PATH(c.payload_json,'one','$.postingContext'))

SELECT COALESCE(SUM(x.physical_qty),0) AS used_qty,
    COALESCE(SUM(CASE WHEN c.state<>'APPLIED' THEN 1 ELSE 0 END),0) AS pending
FROM source_effect f JOIN source_command c ON c.enterprise_id=f.enterprise_id AND c.warehouse_id=f.warehouse_id AND c.business_effect_key=f.id
JOIN source_execution x ON x.enterprise_id=c.enterprise_id AND x.warehouse_id=c.warehouse_id AND x.id=c.source_execution_id
WHERE f.enterprise_id=#{e} AND f.warehouse_id=#{w} AND f.fact_parent_id=#{o} AND f.fact_line_id=#{line}
  AND f.source_service='wms-outbound' AND f.fact_type='SUB_ACTION' AND f.action IN ('PICK','CANCEL')
  AND JSON_UNQUOTE(JSON_EXTRACT(c.payload_json,'$.postingContext.sourceLocationId'))=#{location}
  AND JSON_UNQUOTE(JSON_EXTRACT(c.payload_json,'$.postingContext.lotId'))=#{lot}
